    deviations = []
    for index in range(len(values)):
        previous = values[index - 1] if index > 0 else values[index]
        following = values[index + 1] if index + 1 < len(values) else values[index]
        baseline = sorted((previous, values[index], following))[1]
        deviations.append(abs(values[index] - baseline))
    return deviations


def classify_spikes(deviations: list, hard_limit: int) -> tuple:
    labels = []
    total = 0
    worst = 0
    for deviation in deviations:
        label, score = _classify(deviation, hard_limit)
        labels.append(label)
        total = total + score
        worst = max(worst, score)
    return labels, total, worst


def _classify(deviation: int, hard_limit: int) -> tuple:
    if deviation >= hard_limit:
