from __future__ import annotations

TREND_TOLERANCE = 5

REQUIRED_FIELDS = ("values", "timestamps", "expected_step", "hard_limit")

# (label, deviation gate, score), descending severity.
_SPIKE_TIERS = (
    ("severe", 12, 25),
    ("moderate", 6, 10),
    ("minor", 3, 3),
)
# (cutoff, label) turning a worst score back into a label.
_WORST_TIERS = (
    (100, "invalid"),
    (25, "severe"),
    (10, "moderate"),
    (3, "minor"),
    (0, "clean"),
)
# (cutoff, verdict) grading the total score.
_VERDICT_TIERS = (
    (100, "fail"),
    (25, "warn"),
    (0, "pass"),
)


def qc_series(raw: object) -> dict:
    error = _validate_input(raw)
    if error is not None:
        return {"ok": False, "error": error}
    values = raw["values"]
    timestamps = raw["timestamps"]
    gaps = _count_gaps(timestamps, raw["expected_step"])
    deviations = _deviations(values)
    labels, total, worst = classify_spikes(deviations, raw["hard_limit"])
    return {
        "ok": True,
        "labels": labels,
        "gaps": gaps,
        "score": total,
        "verdict": _pick(total, _VERDICT_TIERS),
        "counts": _label_counts(labels),
        "trend": _trend(values),
        "streak": _longest_run(labels),
        "line": _summary_line(len(values), gaps, worst, total),
    }


def _validate_input(raw: object) -> str | None:
    if not isinstance(raw, dict):
        return "malformed input"
    for key in REQUIRED_FIELDS:
        if key not in raw:
            return "missing field"
    return _series_error(raw["values"], raw["timestamps"]) or _bounds_error(
        raw["expected_step"], raw["hard_limit"]
    )


def _series_error(values: object, timestamps: object) -> str | None:
    if not isinstance(values, list) or len(values) == 0:
        return "bad values"
    if not isinstance(timestamps, list) or len(timestamps) != len(values):
        return "bad timestamps"
    for value, stamp in zip(values, timestamps):
        if not isinstance(value, int) or not isinstance(stamp, int):
            return "bad sample"
    return _order_error(timestamps)


def _order_error(timestamps: list) -> str | None:
    for index in range(1, len(timestamps)):
        if timestamps[index] <= timestamps[index - 1]:
            return "unordered timestamps"
    return None


def _bounds_error(expected_step: object, hard_limit: object) -> str | None:
    for value, message in (
        (expected_step, "bad step"),
        (hard_limit, "bad limit"),
    ):
        if not isinstance(value, int) or value <= 0:
            return message
    return None


def _count_gaps(timestamps: list, expected_step: int) -> int:
    gaps = 0
    for index in range(1, len(timestamps)):
        if timestamps[index] - timestamps[index - 1] > expected_step:
            gaps = gaps + 1
    return gaps


def _deviations(values: list) -> list:
    deviations = []
    for index in range(len(values)):
        previous = values[index - 1] if index > 0 else values[index]
        following = values[index + 1] if index + 1 < len(values) else values[index]
        baseline = sorted((previous, values[index], following))[1]
        deviations.append(abs(values[index] - baseline))
    return deviations


def classify_spikes(deviations: list, hard_limit: int) -> tuple:
    labels = []
    total = 0
    worst = 0
    for deviation in deviations:
        label, score = _classify(deviation, hard_limit)
        labels.append(label)
        total = total + score
        worst = max(worst, score)
    return labels, total, worst


def _classify(deviation: int, hard_limit: int) -> tuple:
    if deviation >= hard_limit:
        return "invalid", 100
    for label, gate, score in _SPIKE_TIERS:
        if deviation >= gate:
            return label, score
    return "clean", 0


def _pick(value: int, tiers: tuple) -> str:
    for cutoff, name in tiers:
        if value >= cutoff:
            return name
    return tiers[-1][1]


def _label_counts(labels: list) -> dict:
    counts = {"clean": 0, "minor": 0, "moderate": 0, "severe": 0, "invalid": 0}
    for label in labels:
        counts[label] = counts[label] + 1
    return counts


def _trend(values: list) -> str:
    delta = values[-1] - values[0]
    if delta > TREND_TOLERANCE:
        return "rising"
    if delta < -TREND_TOLERANCE:
        return "falling"
    return "stable"


def _longest_run(labels: list) -> int:
    longest = 0
    current = 0
    for label in labels:
        if label == "clean":
            current = 0
        else:
            current = current + 1
            if current > longest:
                longest = current
    return longest


def _summary_line(count: int, gaps: int, worst_score: int, total: int) -> str:
    return (
        "n=" + str(count)
        + ";gaps=" + str(gaps)
        + ";worst=" + _pick(worst_score, _WORST_TIERS)
        + ";score=" + str(total)
    )

